package com.studioname.safecracker.model

data class Player(
    val id: PlayerId,
    val displayName: DisplayName,
)

/**
 * We use Firebase anonymous ID, auto-generated by Firebase TODO: migrate to google play service for auth
 */
@JvmInline
value class PlayerId(val value: String) {
    init {
        require(value.isNotBlank()) { "Player ID cannot be blank" }
    }
}

@JvmInline
value class DisplayName(val value: String) {
    init {
        require(value.isNotBlank()) { "Session value cannot be blank" }
        require(value.matches(Regex("^[a-zA-Z0-9_]+$"))) { "value can only contain letters, numbers, and underscores (_)" }
        require(value.length in 2..15) { "value must be between 2 and 15 characters long" }
    }
}